"""[gen] TODO: replace with this world's MCP tools (contract: README.md).

Keep the core tools (brief, observe, note, advance, score) and add one tool per
world verb in `env.actions`. Every tool calls the shared Game with source="agent".
Reference implementation: src/worlds/bike-factory/server/mcp.py
"""

from __future__ import annotations

from typing import Any

from mcp.server.fastmcp import FastMCP


def build_mcp(game: Any) -> FastMCP:
    """Create the MCP server for this world. ``game`` is server.api.Game."""
    mcp = FastMCP("Example world", instructions="Read brief() first. Actions are queued and applied on advance().")

    # ---------- core tools (keep) ----------

    @mcp.tool()
    def brief() -> str:
        """The public brief: story, goal and actions."""
        return game.brief(source="agent")

    @mcp.tool()
    def observe() -> dict[str, Any]:
        """Everything visible now."""
        return game.observe(None, source="agent")

    @mcp.tool()
    def cancel(index: int) -> dict[str, Any]:
        """Remove queued action `index` (0-based, as listed in observe()["queued"]) before advance()."""
        return game.unqueue(index, source="agent")

    @mcp.tool()
    def note(text: str) -> dict[str, Any]:
        """Record a hypothesis you are testing; it is shown in the agent panel."""
        return game.note(text, source="agent")

    @mcp.tool()
    def advance(weeks: int = 1) -> dict[str, Any]:
        """Apply the queued actions and simulate `weeks` weeks."""
        return game.advance(weeks, source="agent")

    @mcp.tool()
    def score() -> dict[str, Any]:
        """Current score (0–1) and the baseline score."""
        return game.score(source="agent")

    # ---------- world verbs (one tool per env.actions entry) ----------

    @mcp.tool()
    def invest(amount: int = 1) -> dict[str, Any]:
        """Queue an investment of `amount` (1–10) units of capacity."""
        return game.act("invest", {"amount": amount}, source="agent")

    return mcp
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

// The world server (server/api.py) serves state and actions under /api.
// Ports come from the environment (the launcher sets them); defaults 8000 / 5173.
const apiPort = process.env.PORT ?? "8000";

export default defineConfig({
  plugins: [react()],
  server: {
    port: Number(process.env.UI_PORT ?? 5173),
    proxy: { "/api": { target: `http://localhost:${apiPort}`, ws: true } },
  },
});
{
  "name": "planworld-ui",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc -b && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "18.3.1",
    "react-dom": "18.3.1"
  },
  "devDependencies": {
    "@types/react": "18.3.12",
    "@types/react-dom": "18.3.1",
    "@vitejs/plugin-react": "4.3.4",
    "typescript": "5.6.3",
    "vite": "5.4.11"
  }
}
// Page layout around the world view. Same in every world; do not edit per world.
import { memo, useCallback, useEffect, useMemo, useState } from "react";
import { sendAction, unqueue, useWorldState } from "./api";
import { ActionDock } from "./shared/controls/ActionDock";
import { AgentPanel } from "./shared/controls/AgentPanel";
import { Brand } from "./shared/controls/Brand";
import { Discoveries } from "./shared/controls/Discoveries";
import { Goal } from "./shared/controls/Goal";
import { Inspector } from "./shared/controls/Inspector";
import { Queue } from "./shared/controls/Queue";
import { StoryToast } from "./shared/controls/StoryToast";
import { TopBar } from "./shared/controls/TopBar";
import type { OnAction, QueuedAction, ScoreInfo } from "./shared/types";
import { mockState, toControls, WorldView } from "./World";

// The SVG world is the heaviest part; redraw it only when its props change.
const MemoWorldView = memo(WorldView);
const ERROR_MS = 3000;

export default function App() {
  const [state, refresh] = useWorldState(mockState);
  // null = the world's default selection.
  const [selectedId, setSelectedId] = useState<string | null>(null);
  // Dock verb shown as active right away, before the server confirms it.
  const [pending, setPending] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const model = useMemo(() => toControls(state, selectedId), [state, selectedId]);
  const queued = (state as { queued?: QueuedAction[] }).queued ?? [];
  const score = (state as { score?: ScoreInfo }).score;

  useEffect(() => setPending(null), [model.dock.active]);
  useEffect(() => {
    if (!error) return;
    const timer = setTimeout(() => setError(null), ERROR_MS);
    return () => clearTimeout(timer);
  }, [error]);

  const run = useCallback(async (id: string, args?: Record<string, unknown>) => {
    const sent = await sendAction(id, { ...args, ...(selectedId ? { target: selectedId } : {}) });
    if (!sent.ok) setError(sent.error ?? "Action rejected");
    await refresh();
    return sent.ok;
  }, [selectedId, refresh]);

  const onAction: OnAction = useCallback((id, args) => void run(id, args), [run]);

  // A dock verb queues that action for the selection, with the inspector's default amount.
  const primary = model.inspector?.primary;
  const verbs = model.dock.verbs;
  const onDock: OnAction = useCallback((id, args) => {
    if (!verbs.some((v) => v.id === id)) return onAction(id, args);
    setPending(id);
    const defaults = primary?.id === id ? { amount: primary.amount } : {};
    void run(id, { ...defaults, ...args }).then((ok) => { if (!ok) setPending(null); });
  }, [verbs, primary, run, onAction]);

  const onRemove = useCallback(async (index: number) => {
    const sent = await unqueue(index);
    if (!sent.ok) setError(sent.error ?? "Could not remove");
    await refresh();
  }, [refresh]);

  const dock = useMemo(() => ({ ...model.dock, active: pending ?? model.dock.active }), [model.dock, pending]);

  return (
    <div className="app">
      <div className="app__glow" />
      <div className="app__brand"><Brand brand={model.brand} /></div>
      <div className="app__top">
        <TopBar topBar={model.topBar} />
        {error ? (
          <div className="story story--coral" role="alert">
            <span className="story__tag">Not queued</span>
            <span>{error}</span>
          </div>
        ) : model.story && <StoryToast story={model.story} />}
      </div>
      <div className="app__world">
        <MemoWorldView state={state} selectedId={selectedId} onSelect={setSelectedId} />
      </div>
      <div className="app__left">
        {model.inspector && <Inspector key={model.inspector.title} model={model.inspector} onAction={onAction} />}
        <Queue queued={queued} onRemove={(k) => void onRemove(k)} />
        <Discoveries discoveries={model.discoveries} />
      </div>
      <div className="app__right">
        <Goal goal={model.goal} score={score} />
        <AgentPanel agent={model.agent} onAction={onAction} />
      </div>
      <div className="app__dock"><ActionDock dock={dock} onAction={onDock} /></div>
    </div>
  );
}
// Connection to the world server (server/api.py, proxied under /api by Vite).
import { useCallback, useEffect, useRef, useState } from "react";

const POLL_MS = 1000;
const OFFLINE_POLL_MS = 5000;

/**
 * Current world state and a `refresh()` to fetch it right away (e.g. after an
 * action). Polls `GET /api/state` every second; until the server answers (or
 * while it is down) the last known state, initially `mock`, is kept, so the UI
 * also works without a server. Unchanged responses keep the same object, so
 * nothing re-renders.
 */
export function useWorldState<T>(mock: T): [T, () => Promise<void>] {
  const [state, setState] = useState<T>(mock);
  const last = useRef("");
  const fetchState = useCallback(async (): Promise<boolean> => {
    try {
      const res = await fetch("/api/state");
      if (!res.ok) return false;
      const text = await res.text();
      if (text !== last.current) {
        last.current = text;
        setState(JSON.parse(text) as T);
      }
      return true;
    } catch {
      return false; // No server: keep the current (mock) state.
    }
  }, []);

  useEffect(() => {
    let alive = true;
    let timer: ReturnType<typeof setTimeout>;
    const poll = async () => {
      const ok = await fetchState();
      // Back off while the server is unreachable to keep the console quiet.
      if (alive) timer = setTimeout(poll, ok ? POLL_MS : OFFLINE_POLL_MS);
    };
    void poll();
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [fetchState]);

  const refresh = useCallback(async () => {
    await fetchState();
  }, [fetchState]);
  return [state, refresh];
}

/** Outcome of a request: `error` is the server's reason when it was rejected. */
export interface Sent { ok: boolean; error?: string }

async function post(path: string, body: unknown): Promise<Sent> {
  try {
    const res = await fetch(path, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (res.ok) return { ok: true };
    const detail = await res.json().then((d: { detail?: unknown }) => d.detail).catch(() => null);
    return { ok: false, error: typeof detail === "string" ? detail : `HTTP ${res.status}` };
  } catch {
    return { ok: false, error: "No connection to the world server" };
  }
}

/** Send a player action (queued until the next advance) or a UI control. */
export function sendAction(id: string, args: Record<string, unknown> = {}): Promise<Sent> {
  return post("/api/action", { id, args });
}

/** Remove queued action `index` of this step. */
export function unqueue(index: number): Promise<Sent> {
  return post("/api/unqueue", { index });
}
// Contract between a world (World.tsx) and the shared controls.
// World.tsx turns its raw state into a ControlsModel; App.tsx renders it.
import type { ReactNode } from "react";

export type Tone = "ink" | "coral" | "mint" | "amber" | "violet" | "muted";
export type IconName =
  | "probe" | "order" | "expand" | "auto" | "lock" | "bolt" | "battery" | "sell"
  | "pause" | "play" | "fast" | "spark" | "check" | "stats";

export interface Stat { label: string; value: string; tone?: Tone }
export interface ProgressBar { label: string; value: string; pct: number; tone: Tone; tick?: number }

export interface InspectorAction {
  id: string;
  label: string;
  sub: string;
  icon: IconName;
  variant: "soft" | "violet" | "locked";
}

export interface InspectorModel {
  title: string;
  level?: number;
  subtitle: string;
  icon?: ReactNode;
  note?: string;
  progress?: ProgressBar;
  stats: Stat[];
  primary?: { id: string; label: string; icon: IconName; amount: number; unit?: string; step: number };
  actions: InspectorAction[];
}

export interface Verb { id: string; label: string; icon: IconName; key: string; disabled?: boolean }

export interface ControlsModel {
  brand: { world: string; seed: string; difficulty: string };
  topBar: { value: string; chips: { text: string; tone: Tone }[]; timeLabel: string; timeProgress: number };
  story?: { tag: string; text: string; tone: "amber" | "mint" | "coral" };
  inspector?: InspectorModel;
  discoveries: { total: number; found: string[]; hidden: (string | null)[] };
  goal: { text: string; bars: ProgressBar[] };
  agent: { experiment: string; mode: "you" | "agent"; scores: number[]; baseline: number; slots: number; now: string; code: string };
  dock: { verbs: Verb[]; active?: string; unlocked: number; total: number };
}

/** One queued action of this step, from `state.queued` (added by the base server). */
export type QueuedAction = { action: string } & Record<string, unknown>;

/** Current score, from `state.score` (added by the base server). */
export interface ScoreInfo { score: number; baseline: number; formula?: string }

/** Called by controls; App forwards it to the world server. */
export type OnAction = (id: string, args?: Record<string, unknown>) => void;
import { Card } from "../primitives/Card";
import { Chip } from "../primitives/Chip";
import type { ControlsModel, OnAction } from "../types";

const W = 220;
const H = 64;
const PAD = 6;

/** You/Agent toggle, experiment score chart, current hypothesis and policy code. */
export function AgentPanel({ agent, onAction }: { agent: ControlsModel["agent"]; onAction: OnAction }) {
  const slots = Math.max(2, agent.slots);
  const x = (k: number) => PAD + (k / (slots - 1)) * (W - 2 * PAD);
  const y = (s: number) => H - PAD - Math.max(0, Math.min(1, s)) * (H - 2 * PAD);
  const line = agent.scores.map((s, k) => `${x(k).toFixed(1)},${y(s).toFixed(1)}`).join(" ");

  return (
    <Card>
      <div className="between">
        <span className="row">
          <i className="agent__dot" />
          <span className="title">Agent</span>
        </span>
        <Chip tone="violet">{agent.experiment}</Chip>
      </div>
      <div className="toggle">
        {(["you", "agent"] as const).map((m) => (
          <button key={m} className={agent.mode === m ? "on" : undefined} onClick={() => onAction("mode", { mode: m })}>
            {m === "you" ? "You" : "Agent"}
          </button>
        ))}
      </div>
      <div className="chart">
        <div className="between">
          <span className="caps">Score / experiment</span>
          <span className="muted">baseline {agent.baseline.toFixed(2)}</span>
        </div>
        <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={H} preserveAspectRatio="none" aria-hidden>
          <line x1={PAD} x2={W - PAD} y1={y(agent.baseline)} y2={y(agent.baseline)} stroke="var(--dim)" strokeWidth="1.2" strokeDasharray="4 3" />
          <polyline points={line} fill="none" stroke="var(--violet)" strokeWidth="2" strokeLinejoin="round" />
          {agent.scores.map((s, k) => (
            <circle key={k} cx={x(k)} cy={y(s)} r={k === agent.scores.length - 1 ? 3.5 : 2.5} fill="var(--violet)" stroke="#fff" strokeWidth="1" />
          ))}
        </svg>
      </div>
      <div className="insp__col">
        <span className="caps">Now testing</span>
        <span className="agent__now">{agent.now}</span>
      </div>
      <pre className="code">{agent.code}</pre>
    </Card>
  );
}

import { useEffect } from "react";
import { Chip } from "../primitives/Chip";
import { Icon } from "../primitives/Icon";
import type { ControlsModel, IconName, OnAction } from "../types";

const timeButtons: { id: string; icon: IconName; label: string }[] = [
  { id: "stats", icon: "stats", label: "Stats" },
  { id: "pause", icon: "pause", label: "Pause" },
  { id: "play", icon: "play", label: "Play" },
  { id: "fast", icon: "fast", label: "Fast forward" },
];

/** Verbs (with keyboard shortcuts), time controls and "New world". */
export function ActionDock({ dock, onAction, running = "play" }: { dock: ControlsModel["dock"]; onAction: OnAction; running?: string }) {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey || (e.target as HTMLElement)?.closest?.("input, textarea")) return;
      const verb = dock.verbs.find((v) => !v.disabled && v.key.toLowerCase() === e.key.toLowerCase());
      if (verb) onAction(verb.id);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [dock.verbs, onAction]);

  return (
    <div className="dock">
      {dock.verbs.map((v) => (
        <button key={v.id} className={`verb${dock.active === v.id ? " on" : ""}`} disabled={v.disabled} onClick={() => onAction(v.id)}>
          <Icon name={v.disabled ? "lock" : v.icon} size={14} />
          {v.label}
          <kbd>{v.key}</kbd>
        </button>
      ))}
      <Chip tone="muted">{dock.unlocked} / {dock.total} actions</Chip>
      <span className="dock__sep" />
      {timeButtons.map((b) => (
        <button key={b.id} className={`iconbtn${running === b.id ? " on" : ""}`} aria-label={b.label} title={b.label} onClick={() => onAction(b.id)}>
          <Icon name={b.icon} size={14} />
        </button>
      ))}
      <span className="dock__sep" />
      <button className="btn btn--coral" onClick={() => onAction("new_world")}>
        <Icon name="spark" size={14} />
        New world
      </button>
    </div>
  );
}
import { Bar } from "../primitives/Bar";
import { Chip } from "../primitives/Chip";
import type { ControlsModel } from "../types";

/** Main number (cash, bill, …), rate chips and time progress. */
export function TopBar({ topBar }: { topBar: ControlsModel["topBar"] }) {
  return (
    <div className="topbar">
      <div className="row">
        <span className="topbar__value">{topBar.value}</span>
        {topBar.chips.map((c) => (
          <Chip key={c.text} tone={c.tone}>{c.text}</Chip>
        ))}
      </div>
      <div className="topbar__time">
        <span>{topBar.timeLabel}</span>
        <Bar pct={topBar.timeProgress} tone="ink" />
      </div>
    </div>
  );
}
import { useState } from "react";
import { Bar } from "../primitives/Bar";
import { Card } from "../primitives/Card";
import { Chip } from "../primitives/Chip";
import { Icon } from "../primitives/Icon";
import type { InspectorModel, OnAction, Tone } from "../types";

const toneColor: Partial<Record<Tone, string>> = {
  coral: "var(--coral)", mint: "var(--mint)", amber: "#c47f00", violet: "var(--violet)", muted: "var(--muted)",
};

/**
 * Selected object. App renders it with `key={title}` so the stepper amount
 * resets when the selection changes.
 */
export function Inspector({ model, onAction }: { model: InspectorModel; onAction: OnAction }) {
  const { primary } = model;
  const [amount, setAmount] = useState(primary?.amount ?? 0);

  return (
    <Card className="inspector">
      <div className="row">
        <div className="insp__icon">{model.icon}</div>
        <div className="insp__head">
          <div className="row">
            <span className="title">{model.title}</span>
            {model.level != null && <Chip tone="ink">LV {model.level}</Chip>}
          </div>
          <div className="muted">{model.subtitle}</div>
        </div>
      </div>

      {model.note && <div className="insp__note">{model.note}</div>}

      {model.progress && (
        <div className="insp__progress">
          <div className="between">
            <span className="caps">{model.progress.label}</span>
            <span className="stat__value">{model.progress.value}</span>
          </div>
          <Bar pct={model.progress.pct} tone={model.progress.tone} tick={model.progress.tick} height={10} />
        </div>
      )}

      {model.stats.length > 0 && (
        <div className="stats">
          {model.stats.map((s) => (
            <div key={s.label} className="stat">
              <span className="caps">{s.label}</span>
              <span className="stat__value" style={s.tone ? { color: toneColor[s.tone] } : undefined}>{s.value}</span>
            </div>
          ))}
        </div>
      )}

      {primary && (
        <div className="row">
          <div className="stepper">
            <button aria-label="less" onClick={() => setAmount((a) => Math.max(0, a - primary.step))}>−</button>
            <span>{amount}{primary.unit ?? ""}</span>
            <button aria-label="more" onClick={() => setAmount((a) => a + primary.step)}>+</button>
          </div>
          <button className="btn btn--ink" onClick={() => onAction(primary.id, { amount })}>
            <Icon name={primary.icon} size={14} />
            {primary.label} {amount}
          </button>
        </div>
      )}

      {model.actions.map((a) => (
        <button
          key={a.id}
          className={`action action--${a.variant}`}
          disabled={a.variant === "locked"}
          onClick={() => onAction(a.id)}
        >
          <Icon name={a.variant === "locked" ? "lock" : a.icon} size={16} />
          <span className="insp__col">
            <span className="action__label">{a.label}</span>
            <span className="action__sub">{a.sub}</span>
          </span>
        </button>
      ))}
    </Card>
  );
}
import type { ReactNode } from "react";
import { Bar } from "./Bar";

interface HudProps {
  /** Position in percent of the world view (from kit `toPercent`). */
  x: number;
  y: number;
  label: string;
  level?: number | string;
  pct?: number;
  color?: string;
  tag?: ReactNode;
  selected?: boolean;
  alert?: boolean;
  onClick?: () => void;
}

/** Map label pill shown above an object in the world view. */
export function Hud({ x, y, label, level, pct, color, tag, selected, alert, onClick }: HudProps) {
  const cls = ["hud", selected && "hud--selected", alert && "hud--alert"].filter(Boolean).join(" ");
  return (
    <div className={cls} style={{ left: `${x}%`, top: `${y}%` }} onClick={onClick}>
      {level != null && <span className="hud__lv">{level}</span>}
      <span>{label}</span>
      {pct != null && !alert && <Bar pct={pct} color={color} />}
      {tag}
    </div>
  );
}
import type { IconName } from "../types";

const paths: Record<IconName, JSX.Element> = {
  probe: <><circle cx="6" cy="6" r="5" fill="none" stroke="currentColor" strokeWidth="2" /><path d="M10 10l5 5" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" /></>,
  order: <><rect x="2" y="4" width="12" height="10" rx="2" fill="none" stroke="currentColor" strokeWidth="2" /><path d="M2 7h12" stroke="currentColor" strokeWidth="1.6" /></>,
